abstract class Car {
    void start() {
        System.out.println("Car started");
    }
    abstract void accelerate();
    abstract void brake();
}

class FuelCar extends Car {
    @Override
    void accelerate() {
        System.out.println("Fuel car is accelerating");
    }
    @Override
    void brake() {
        System.out.println("Fuel car is stopping");
    }
}

public class Demo {
    public static void main(String[] args) {
        Car car = new FuelCar();
        car.start();
        car.accelerate();
        car.brake();
    }
}

